#!/usr/bin/env node
/**
 * Generates TypeScript types, metadata, and resource classes from recorded Kong Admin API schemas.
 *
 * Usage:
 *   node scripts/generate.mjs          # write generated files
 *   node scripts/generate.mjs --check  # verify committed files are up to date
 */

import { mkdir, readdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import prettier from 'prettier';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(__dirname, '..');

const TARGET_39 = 'kong-3.9';
const TARGET_314 = 'kong-gateway-3.14';
const LABEL_39 = 'Kong 3.9';
const LABEL_314 = 'Kong Gateway 3.14';

const GENERATED_BANNER = '// Code generated by scripts/generate.mjs. DO NOT EDIT.\n\n';
const IDENTIFIER_RE = /^[A-Za-z_$][A-Za-z0-9_$]*$/;

/**
 * Input fields accepted by Kong's Admin API that are not listed in GET /schemas/<entity>.
 * Verified against both Kong 3.9 and Kong Gateway 3.14.
 */
const ENTITY_INPUT_OVERRIDES = {
  services: {
    makeOptional: new Set(['host']),
    extraFields: [
      {
        name: 'url',
        type: 'string',
        optional: true,
        nullable: false,
        jsdocLines: [
          'Shorthand URL to set protocol, host, port, and path together (for example `https://example.com:8443/api`).',
        ],
      },
    ],
  },
};

function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function stableStringify(value) {
  if (Array.isArray(value)) {
    return `[${value.map(stableStringify).join(',')}]`;
  }
  if (isPlainObject(value)) {
    const entries = Object.keys(value)
      .sort()
      .map((k) => `${JSON.stringify(k)}:${stableStringify(value[k])}`);
    return `{${entries.join(',')}}`;
  }
  return JSON.stringify(value);
}

function escapeJsDoc(text) {
  return String(text).replaceAll('*/', '*\\/').replaceAll('\r\n', '\n').trim();
}

function formatPropName(name) {
  return IDENTIFIER_RE.test(name) ? name : JSON.stringify(name);
}

function formatLiteral(value) {
  if (typeof value === 'string') {
    return `'${value.replaceAll('\\', '\\\\').replaceAll("'", "\\'")}'`;
  }
  return String(value);
}

function formatDefaultValue(value) {
  if (typeof value === 'string') {
    return escapeJsDoc(formatLiteral(value));
  }
  return escapeJsDoc(JSON.stringify(value));
}

function formatJsDoc(lines, indent = '') {
  const cleaned = [];
  for (const raw of lines) {
    const text = escapeJsDoc(raw);
    if (!text) {
      continue;
    }
    for (const subline of text.split('\n')) {
      cleaned.push(subline.trimEnd());
    }
  }
  if (cleaned.length === 0) {
    return '';
  }
  if (cleaned.length === 1) {
    return `${indent}/** ${cleaned[0]} */\n`;
  }
  const body = cleaned.map((line) => (line ? `${indent} * ${line}` : `${indent} *`)).join('\n');
  return `${indent}/**\n${body}\n${indent} */\n`;
}

function capitalize(str) {
  return str ? str[0].toUpperCase() + str.slice(1) : '';
}

function lowerCamel(str) {
  return str ? str[0].toLowerCase() + str.slice(1) : '';
}

function pluginConfigInterfaceName(pluginName) {
  return pluginName.split('-').map(capitalize).join('') + 'Config';
}

function resourceClassName(resourceKey) {
  return `${capitalize(resourceKey)}Resource`;
}

function fieldsArrayToMap(fieldsList) {
  const map = new Map();
  for (const entry of fieldsList ?? []) {
    if (!isPlainObject(entry)) {
      continue;
    }
    for (const [name, def] of Object.entries(entry)) {
      map.set(name, def);
    }
  }
  return map;
}

function mergeFieldMaps(list39, list314) {
  const map39 = fieldsArrayToMap(list39);
  const map314 = fieldsArrayToMap(list314);
  const merged = [];
  for (const [name, def39] of map39.entries()) {
    merged.push({ name, def39, def314: map314.get(name) });
  }
  for (const [name, def314] of map314.entries()) {
    if (!map39.has(name)) {
      merged.push({ name, def39: undefined, def314 });
    }
  }
  return merged;
}

function hasNonNullDefault(def) {
  return def !== undefined && 'default' in def && def.default !== undefined && def.default !== null;
}

function mergeOneOf(oneOf39, oneOf314) {
  const a = Array.isArray(oneOf39) ? oneOf39 : undefined;
  const b = Array.isArray(oneOf314) ? oneOf314 : undefined;
  if (!a && !b) {
    return null;
  }
  if (a && !b) {
    return { values: [...a], only39: [], only314: [] };
  }
  if (!a && b) {
    return { values: [...b], only39: [], only314: [] };
  }
  const setA = new Set(a);
  const setB = new Set(b);
  const values = [...a, ...b.filter((v) => !setA.has(v))];
  const only39 = a.filter((v) => !setB.has(v));
  const only314 = b.filter((v) => !setA.has(v));
  return { values, only39, only314 };
}

function isRequiredEverywhere(def39, def314) {
  if (def39 && def314) {
    return def39.required === true && def314.required === true;
  }
  const sole = def39 ?? def314;
  return sole?.required === true;
}

function isAutoEverywhere(def39, def314) {
  if (def39 && def314) {
    return def39.auto === true && def314.auto === true;
  }
  const sole = def39 ?? def314;
  return sole?.auto === true;
}

function isAbstractOrEmptyRecord(def) {
  if (!def) {
    return true;
  }
  return def.abstract === true || !Array.isArray(def.fields) || def.fields.length === 0;
}

/**
 * Determines whether a field is required in an accepted (input/config) payload.
 *
 * A field is required only when:
 * - it exists in both targets (or in the sole target if inside a single-target record)
 * - `required` is true wherever it exists
 * - it has no non-null `default` in either target
 * - it is not `auto` in either target
 * - if it is a concrete `record`, at least one of its subfields is itself required
 *   (Kong auto-populates records whose subfields all have defaults or are optional).
 */
function isRequiredInInput(def39, def314, insideSingleTarget = false) {
  const presentInBoth = def39 !== undefined && def314 !== undefined;
  if (!insideSingleTarget && !presentInBoth) {
    return false;
  }
  if (!isRequiredEverywhere(def39, def314)) {
    return false;
  }
  if (hasNonNullDefault(def39) || hasNonNullDefault(def314)) {
    return false;
  }
  if (def39?.auto === true || def314?.auto === true) {
    return false;
  }

  const type39 = def39?.type;
  const type314 = def314?.type;
  const isRecord =
    (type39 === undefined || type39 === 'record') &&
    (type314 === undefined || type314 === 'record');
  if (isRecord) {
    if (isAbstractOrEmptyRecord(def39) && isAbstractOrEmptyRecord(def314)) {
      return false;
    }
    const subFields = mergeFieldMaps(def39?.fields, def314?.fields);
    return subFields.some((sub) =>
      isRequiredInInput(sub.def39, sub.def314, insideSingleTarget || !presentInBoth),
    );
  }
  return true;
}

function collectNestedOneOfNotes(def39, def314, notes) {
  const merged = mergeOneOf(def39?.one_of, def314?.one_of);
  if (merged) {
    if (merged.only39.length > 0) {
      notes.push(
        `${LABEL_39} only values: ${merged.only39.map((v) => `\`${formatLiteral(v)}\``).join(', ')}.`,
      );
    }
    if (merged.only314.length > 0) {
      notes.push(
        `${LABEL_314} only values: ${merged.only314.map((v) => `\`${formatLiteral(v)}\``).join(', ')}.`,
      );
    }
  }
  if (def39?.elements || def314?.elements) {
    collectNestedOneOfNotes(def39?.elements, def314?.elements, notes);
  }
}

function buildFieldJsDocLines(def39, def314, options = {}) {
  const { isShorthand = false, suppressTargetNote = false } = options;
  const lines = [];

  if (def39?.description) {
    lines.push(def39.description);
  }

  if (!suppressTargetNote) {
    if (def39 && !def314) {
      lines.push(`${LABEL_39} only.`);
    } else if (!def39 && def314) {
      lines.push(`${LABEL_314} only.`);
    }
  }

  if (def39 && def314 && def39.type && def314.type && def39.type !== def314.type) {
    lines.push(
      `Type differs between targets: ${LABEL_39} uses \`${def39.type}\`; ${LABEL_314} uses \`${def314.type}\`.`,
    );
  }

  collectNestedOneOfNotes(def39, def314, lines);

  const hasDef39 = hasNonNullDefault(def39);
  const hasDef314 = hasNonNullDefault(def314);
  if (def39 && def314) {
    if (hasDef39 && hasDef314) {
      const s39 = stableStringify(def39.default);
      const s314 = stableStringify(def314.default);
      if (s39 === s314) {
        lines.push(`@default ${formatDefaultValue(def39.default)}`);
      } else {
        lines.push(
          `@default ${LABEL_39}: ${formatDefaultValue(def39.default)}; ${LABEL_314}: ${formatDefaultValue(def314.default)}`,
        );
      }
    } else if (hasDef39) {
      lines.push(`@default ${LABEL_39}: ${formatDefaultValue(def39.default)}; ${LABEL_314}: none`);
    } else if (hasDef314) {
      lines.push(`@default ${LABEL_39}: none; ${LABEL_314}: ${formatDefaultValue(def314.default)}`);
    }
  } else if (hasDef39) {
    lines.push(`@default ${formatDefaultValue(def39.default)}`);
  } else if (hasDef314) {
    lines.push(`@default ${formatDefaultValue(def314.default)}`);
  }

  if (def39?.deprecation) {
    const dep = def39.deprecation;
    if (isPlainObject(dep) && typeof dep.message === 'string' && dep.message.trim()) {
      lines.push(`@deprecated ${dep.message.trim()}`);
    } else {
      lines.push('@deprecated');
    }
  } else if (isShorthand && def39?.description?.toLowerCase().includes('deprecated')) {
    lines.push('@deprecated');
  }

  return lines;
}

function renderForeignAcceptedType(reference, entityContext) {
  const variants = ['{ id: string }'];
  if (reference === 'consumers') {
    variants.push('{ username: string }');
  } else if (reference && entityContext.uniqueNameEntities.has(reference)) {
    variants.push('{ name: string }');
  }
  return variants.join(' | ');
}

function renderSingleType(def39, def314, mode, insideSingleTarget, entityContext) {
  const sole = def39 ?? def314;
  const kongType = sole.type;

  switch (kongType) {
    case 'string': {
      const merged = mergeOneOf(def39?.one_of, def314?.one_of);
      if (merged && merged.values.length > 0) {
        return merged.values.map(formatLiteral).join(' | ');
      }
      return 'string';
    }
    case 'integer':
    case 'number': {
      const merged = mergeOneOf(def39?.one_of, def314?.one_of);
      if (merged && merged.values.length > 0) {
        return merged.values.map(formatLiteral).join(' | ');
      }
      return 'number';
    }
    case 'boolean':
      return 'boolean';
    case 'array':
    case 'set': {
      const elem39 = def39?.elements;
      const elem314 = def314?.elements;
      if (!elem39 && !elem314) {
        return 'Array<unknown>';
      }
      const elemType = renderType(elem39, elem314, mode, insideSingleTarget, entityContext);
      return `Array<${elemType}>`;
    }
    case 'map': {
      const val39 = def39?.values;
      const val314 = def314?.values;
      if (!val39 && !val314) {
        return 'Record<string, unknown>';
      }
      const valType = renderType(val39, val314, mode, insideSingleTarget, entityContext);
      return `Record<string, ${valType}>`;
    }
    case 'foreign': {
      if (mode === 'returned') {
        return '{ id: string }';
      }
      const ref = def39?.reference ?? def314?.reference;
      return renderForeignAcceptedType(ref, entityContext);
    }
    case 'json':
      return 'unknown';
    case 'record': {
      if (isAbstractOrEmptyRecord(def39) && isAbstractOrEmptyRecord(def314)) {
        return 'Record<string, unknown>';
      }
      const body = renderRecordMembers(def39, def314, mode, insideSingleTarget, entityContext);
      return `{\n${body}}`;
    }
    default:
      return 'unknown';
  }
}

function renderType(def39, def314, mode, insideSingleTarget, entityContext) {
  const type39 = def39?.type;
  const type314 = def314?.type;
  if (type39 && type314 && type39 !== type314) {
    const t39 = renderSingleType(def39, undefined, mode, true, entityContext);
    const t314 = renderSingleType(undefined, def314, mode, true, entityContext);
    return t39 === t314 ? t39 : `${t39} | ${t314}`;
  }
  return renderSingleType(def39, def314, mode, insideSingleTarget, entityContext);
}

function withNullable(tsType) {
  if (tsType === 'unknown' || tsType.endsWith('| null')) {
    return tsType;
  }
  return `${tsType} | null`;
}

function renderRecordMembers(rec39, rec314, mode, insideSingleTarget, entityContext, options = {}) {
  const { entityName = undefined, isTopLevelEntity = false } = options;
  const overrides =
    isTopLevelEntity && mode === 'accepted' ? ENTITY_INPUT_OVERRIDES[entityName] : undefined;
  const parentSingleTarget = insideSingleTarget || rec39 === undefined || rec314 === undefined;

  const lines = [];
  const regularFields = mergeFieldMaps(rec39?.fields, rec314?.fields);
  const regularNames = new Set(regularFields.map((f) => f.name));

  for (const { name, def39, def314 } of regularFields) {
    if (
      isTopLevelEntity &&
      mode === 'accepted' &&
      (name === 'created_at' || name === 'updated_at')
    ) {
      continue;
    }

    const fieldSingleTarget = parentSingleTarget || def39 === undefined || def314 === undefined;
    const jsdocLines = buildFieldJsDocLines(def39, def314, {
      suppressTargetNote: parentSingleTarget,
    });
    const jsdoc = formatJsDoc(jsdocLines);

    // Special generic handling for the `plugins` entity's `name` and `config` fields.
    if (isTopLevelEntity && entityName === 'plugins' && name === 'name') {
      lines.push(`${jsdoc}${formatPropName(name)}: N;`);
      continue;
    }
    if (isTopLevelEntity && entityName === 'plugins' && name === 'config') {
      if (mode === 'returned') {
        lines.push(`${jsdoc}${formatPropName(name)}: ConfigOf<N>;`);
      } else {
        lines.push(`${jsdoc}${formatPropName(name)}?: ConfigOf<N> | null;`);
      }
      continue;
    }

    const tsType = renderType(def39, def314, mode, fieldSingleTarget, entityContext);

    if (mode === 'returned') {
      const onlyInOneTarget = !parentSingleTarget && (def39 === undefined || def314 === undefined);
      const nonNull = isRequiredEverywhere(def39, def314) || isAutoEverywhere(def39, def314);
      const finalType = nonNull ? tsType : withNullable(tsType);
      const opt = onlyInOneTarget ? '?' : '';
      lines.push(`${jsdoc}${formatPropName(name)}${opt}: ${finalType};`);
    } else {
      const forcedOptional =
        (isTopLevelEntity && name === 'id') || Boolean(overrides?.makeOptional?.has(name));
      const required = !forcedOptional && isRequiredInInput(def39, def314, parentSingleTarget);
      if (required) {
        lines.push(`${jsdoc}${formatPropName(name)}: ${tsType};`);
      } else {
        lines.push(`${jsdoc}${formatPropName(name)}?: ${withNullable(tsType)};`);
      }
    }
  }

  if (overrides?.extraFields) {
    for (const extra of overrides.extraFields) {
      const jsdoc = formatJsDoc(extra.jsdocLines);
      const opt = extra.optional ? '?' : '';
      const finalType = extra.nullable ? withNullable(extra.type) : extra.type;
      lines.push(`${jsdoc}${formatPropName(extra.name)}${opt}: ${finalType};`);
    }
  }

  const shorthandFields = mergeFieldMaps(rec39?.shorthand_fields, rec314?.shorthand_fields);
  for (const { name, def39, def314 } of shorthandFields) {
    if (regularNames.has(name)) {
      continue;
    }
    const fieldSingleTarget = parentSingleTarget || def39 === undefined || def314 === undefined;
    const jsdocLines = buildFieldJsDocLines(def39, def314, {
      isShorthand: true,
      suppressTargetNote: parentSingleTarget,
    });
    const jsdoc = formatJsDoc(jsdocLines);
    const tsType = renderType(def39, def314, mode, fieldSingleTarget, entityContext);
    lines.push(`${jsdoc}${formatPropName(name)}?: ${withNullable(tsType)};`);
  }

  return lines.join('\n') + (lines.length > 0 ? '\n' : '');
}

async function readJson(filePath) {
  return JSON.parse(await readFile(filePath, 'utf8'));
}

async function readJsonIfExists(filePath) {
  try {
    return await readJson(filePath);
  } catch (err) {
    if (err && typeof err === 'object' && 'code' in err && err.code === 'ENOENT') {
      return undefined;
    }
    throw err;
  }
}

async function listJsonNames(dirPath) {
  const entries = await readdir(dirPath);
  return entries
    .filter((file) => file.endsWith('.json'))
    .map((file) => file.slice(0, -'.json'.length))
    .sort();
}

async function loadEntityContext(resourcesJson) {
  const dir39 = path.join(REPO_ROOT, 'schemas', TARGET_39, 'entities');
  const dir314 = path.join(REPO_ROOT, 'schemas', TARGET_314, 'entities');

  const entityNames = new Set([
    ...(await listJsonNames(dir39)),
    ...(await listJsonNames(dir314)),
    ...Object.values(resourcesJson.resources).map((r) => r.entity),
  ]);

  const schemas39 = new Map();
  const schemas314 = new Map();
  const uniqueNameEntities = new Set();

  for (const entity of [...entityNames].sort()) {
    const s39 = await readJsonIfExists(path.join(dir39, `${entity}.json`));
    const s314 = await readJsonIfExists(path.join(dir314, `${entity}.json`));
    if (s39) {
      schemas39.set(entity, s39);
    }
    if (s314) {
      schemas314.set(entity, s314);
    }
    if (!s39 && !s314) {
      continue;
    }

    // Read `unique` from the kong-3.9 recording (structure-only 3.14 omits `unique`).
    const name39 = s39 ? fieldsArrayToMap(s39.fields).get('name') : undefined;
    if (name39?.unique === true) {
      uniqueNameEntities.add(entity);
    }
  }

  return { schemas39, schemas314, uniqueNameEntities };
}

function extractPluginScopes(schema39, schema314) {
  const fields39 = fieldsArrayToMap(schema39?.fields);
  const fields314 = fieldsArrayToMap(schema314?.fields);
  const scopes = ['global', 'service', 'route', 'consumer'];
  for (const scope of ['service', 'route', 'consumer']) {
    const f39 = fields39.get(scope);
    const f314 = fields314.get(scope);
    const pinnedNull39 = f39 !== undefined && 'eq' in f39 && f39.eq === null;
    const pinnedNull314 = f314 !== undefined && 'eq' in f314 && f314.eq === null;
    if (pinnedNull39 || pinnedNull314) {
      const idx = scopes.indexOf(scope);
      if (idx !== -1) {
        scopes.splice(idx, 1);
      }
    }
  }
  return scopes;
}

function extractPluginProtocols(schema39, schema314) {
  const p39 = fieldsArrayToMap(schema39?.fields).get('protocols')?.elements?.one_of ?? [];
  const p314 = fieldsArrayToMap(schema314?.fields).get('protocols')?.elements?.one_of ?? [];
  const merged = mergeOneOf(p39, p314);
  return merged ? merged.values : [];
}

function findForeignFieldsReferencing(childEntity, parentEntity, entityContext) {
  const s39 = entityContext.schemas39.get(childEntity);
  const s314 = entityContext.schemas314.get(childEntity);
  const merged = mergeFieldMaps(s39?.fields, s314?.fields);
  const matches = [];
  for (const { name, def39, def314 } of merged) {
    const def = def39 ?? def314;
    if (def?.type === 'foreign' && def.reference === parentEntity) {
      matches.push(name);
    }
  }
  return matches;
}

async function generatePluginsSource(entityContext) {
  const categoriesJson = await readJson(path.join(REPO_ROOT, 'schemas', 'plugin-categories.json'));
  const dir39 = path.join(REPO_ROOT, 'schemas', TARGET_39, 'plugins');
  const dir314 = path.join(REPO_ROOT, 'schemas', TARGET_314, 'plugins');

  const names39 = await listJsonNames(dir39);
  const names314Set = new Set(await listJsonNames(dir314));
  const pluginNames = [...new Set([...names39, ...names314Set])].sort();

  const chunks = [GENERATED_BANNER];
  const configMapEntries = [];
  const pluginsMetadataEntries = [];

  for (const pluginName of pluginNames) {
    const schema39 = await readJsonIfExists(path.join(dir39, `${pluginName}.json`));
    const schema314 = await readJsonIfExists(path.join(dir314, `${pluginName}.json`));
    const config39 = fieldsArrayToMap(schema39?.fields).get('config');
    const config314 = fieldsArrayToMap(schema314?.fields).get('config');

    const meta = categoriesJson.plugins[pluginName];
    if (!meta) {
      throw new Error(`Plugin "${pluginName}" is missing from schemas/plugin-categories.json`);
    }

    const ifaceName = pluginConfigInterfaceName(pluginName);
    const members = renderRecordMembers(config39, config314, 'accepted', false, entityContext);
    const ifaceDoc = formatJsDoc([
      `Configuration for the \`${pluginName}\` (${meta.title}) plugin.`,
    ]);
    chunks.push(`${ifaceDoc}export interface ${ifaceName} {\n${members}}\n`);

    configMapEntries.push(`${formatPropName(pluginName)}: ${ifaceName};`);

    const targets = [];
    if (schema39) {
      targets.push(TARGET_39);
    }
    if (schema314) {
      targets.push(TARGET_314);
    }
    const scopes = extractPluginScopes(schema39, schema314);
    const protocols = extractPluginProtocols(schema39, schema314);

    pluginsMetadataEntries.push(
      `${formatPropName(pluginName)}: {\n` +
        `category: ${formatLiteral(meta.category)},\n` +
        `title: ${formatLiteral(meta.title)},\n` +
        `targets: [${targets.map(formatLiteral).join(', ')}],\n` +
        `scopes: [${scopes.map(formatLiteral).join(', ')}],\n` +
        `protocols: [${protocols.map(formatLiteral).join(', ')}],\n` +
        `},`,
    );
  }

  chunks.push(
    formatJsDoc(['Mapping from first-class Kong plugin name to its configuration type.']) +
      `export interface PluginConfigs {\n${configMapEntries.join('\n')}\n}\n`,
  );

  chunks.push(
    formatJsDoc(['Union of all first-class Kong plugin names.']) +
      'export type PluginName = keyof PluginConfigs;\n',
  );

  chunks.push(
    formatJsDoc([
      'Configuration type for plugin `N`, falling back to `Record<string, unknown>` for custom plugins.',
    ]) +
      'export type ConfigOf<N extends string> = N extends PluginName ? PluginConfigs[N] : Record<string, unknown>;\n',
  );

  chunks.push(
    formatJsDoc(['Scope at which a Kong plugin can be attached.']) +
      "export type PluginScopeName = 'global' | 'service' | 'route' | 'consumer';\n",
  );

  chunks.push(
    formatJsDoc(['Metadata describing a first-class Kong plugin.']) +
      'export interface PluginInfo {\n' +
      '/** Plugin category. */\nreadonly category: string;\n' +
      '/** Human-readable plugin title. */\nreadonly title: string;\n' +
      '/** Recorded Kong targets that include this plugin. */\nreadonly targets: readonly string[];\n' +
      '/** Scopes at which the plugin can be attached. */\nreadonly scopes: readonly PluginScopeName[];\n' +
      '/** Protocols supported by the plugin across recorded targets. */\nreadonly protocols: readonly string[];\n' +
      '}\n',
  );

  chunks.push(
    formatJsDoc(['Metadata for every first-class Kong plugin, keyed by plugin name.']) +
      `export const PLUGINS: Readonly<Record<PluginName, PluginInfo>> = {\n${pluginsMetadataEntries.join('\n')}\n};\n`,
  );

  return chunks.join('\n');
}

function generateEntitiesSource(resourcesJson, entityContext) {
  const chunks = [GENERATED_BANNER, "import type { ConfigOf } from './plugins.js';\n"];

  for (const resource of Object.values(resourcesJson.resources)) {
    const { entity, type: typeName } = resource;
    const schema39 = entityContext.schemas39.get(entity);
    const schema314 = entityContext.schemas314.get(entity);
    if (!schema39 && !schema314) {
      throw new Error(`Missing recorded entity schema for "${entity}"`);
    }

    const isPlugin = entity === 'plugins';
    const genericClause = isPlugin ? '<N extends string = string>' : '';

    const returnedMembers = renderRecordMembers(
      schema39,
      schema314,
      'returned',
      false,
      entityContext,
      {
        entityName: entity,
        isTopLevelEntity: true,
      },
    );
    const returnedDoc = formatJsDoc([`Kong \`${entity}\` entity returned by the Admin API.`]);
    chunks.push(
      `${returnedDoc}export interface ${typeName}${genericClause} {\n${returnedMembers}}\n`,
    );

    const acceptedMembers = renderRecordMembers(
      schema39,
      schema314,
      'accepted',
      false,
      entityContext,
      {
        entityName: entity,
        isTopLevelEntity: true,
      },
    );
    const acceptedDoc = formatJsDoc([
      `Input payload accepted by Kong when creating or updating a \`${entity}\` entity.`,
    ]);
    chunks.push(
      `${acceptedDoc}export interface ${typeName}Input${genericClause} {\n${acceptedMembers}}\n`,
    );
  }

  return chunks.join('\n');
}

function generateResourcesSource(resourcesJson, entityContext) {
  const resources = resourcesJson.resources;
  const importedEntityTypes = new Set();
  const customClassImports = new Map();
  let usesCollection = false;
  let usesSingleton = false;
  let usesSegment = false;

  const templates = [];
  const classBlocks = [];
  const kongResourcesProps = [];
  const kongResourcesInits = [];

  function registerCustomClass(collectionClass) {
    let names = customClassImports.get(collectionClass.module);
    if (!names) {
      names = new Set();
      customClassImports.set(collectionClass.module, names);
    }
    names.add(collectionClass.name);
  }

  for (const [resourceKey, def] of Object.entries(resources)) {
    if (def.topLevel === false) {
      continue;
    }

    templates.push(`/${def.path}`, `/${def.path}/{}`);

    const className = resourceClassName(resourceKey);
    const paramName = lowerCamel(def.type);

    let extendsClause;
    if (def.collectionClass) {
      registerCustomClass(def.collectionClass);
      extendsClause = def.collectionClass.name;
    } else {
      usesCollection = true;
      importedEntityTypes.add(def.type);
      importedEntityTypes.add(`${def.type}Input`);
      extendsClause = `Collection<${def.type}, ${def.type}Input>`;
    }

    const methods = [];

    for (const [methodName, nested] of Object.entries(def.nested ?? {})) {
      const child = resources[nested.resource];
      if (!child) {
        throw new Error(`Unknown nested resource "${nested.resource}" on "${resourceKey}"`);
      }
      templates.push(`/${def.path}/{}/${nested.path}`, `/${def.path}/{}/${nested.path}/{}`);
      usesSegment = true;

      const routeTemplate = `/${def.path}/{${paramName}}/${nested.path}`;
      const pathExpr = `\`/${def.path}/\${segment(${paramName})}/${nested.path}\``;
      const doc = formatJsDoc([`Nested \`${nested.path}\` collection: \`${routeTemplate}\`.`]);

      if (child.collectionClass) {
        registerCustomClass(child.collectionClass);
        methods.push(
          `${doc}${methodName}(${paramName}: string): ${child.collectionClass.name} {\n` +
            `return new ${child.collectionClass.name}(this.transport, ${pathExpr});\n` +
            `}`,
        );
      } else {
        usesCollection = true;
        importedEntityTypes.add(child.type);
        importedEntityTypes.add(`${child.type}Input`);
        const foreignKeys = findForeignFieldsReferencing(child.entity, def.entity, entityContext);
        const inputType =
          foreignKeys.length > 0
            ? `NestedInput<${child.type}Input, ${foreignKeys.map(formatLiteral).join(' | ')}>`
            : `${child.type}Input`;
        methods.push(
          `${doc}${methodName}(${paramName}: string): Collection<${child.type}, ${inputType}> {\n` +
            `return new Collection<${child.type}, ${inputType}>(this.transport, ${pathExpr});\n` +
            `}`,
        );
      }
    }

    for (const [methodName, single] of Object.entries(def.single ?? {})) {
      const target = resources[single.resource];
      if (!target) {
        throw new Error(`Unknown single resource "${single.resource}" on "${resourceKey}"`);
      }
      templates.push(`/${def.path}/{}/${single.path}`);
      usesSingleton = true;
      usesSegment = true;
      importedEntityTypes.add(target.type);
      importedEntityTypes.add(`${target.type}Input`);

      const routeTemplate = `/${def.path}/{${paramName}}/${single.path}`;
      const pathExpr = `\`/${def.path}/\${segment(${paramName})}/${single.path}\``;
      const doc = formatJsDoc([`Related \`${single.path}\` singleton: \`${routeTemplate}\`.`]);
      methods.push(
        `${doc}${methodName}(${paramName}: string): Singleton<${target.type}, ${target.type}Input> {\n` +
          `return new Singleton<${target.type}, ${target.type}Input>(this.transport, ${pathExpr});\n` +
          `}`,
      );
    }

    const classDoc = formatJsDoc([`Admin API resource for \`/${def.path}\`.`]);
    const ctorDoc = formatJsDoc([`Creates the \`${className}\` bound to the given transport.`]);
    const bodyLines = [
      `${ctorDoc}constructor(transport: Transport) {\nsuper(transport, ${formatLiteral(`/${def.path}`)});\n}`,
      ...methods,
    ];
    classBlocks.push(
      `${classDoc}export class ${className} extends ${extendsClause} {\n${bodyLines.join('\n\n')}\n}\n`,
    );

    kongResourcesProps.push(
      `${formatJsDoc([`Resource endpoints under \`/${def.path}\`.`])}readonly ${resourceKey}: ${className};`,
    );
    kongResourcesInits.push(`this.${resourceKey} = new ${className}(transport);`);
  }

  const importLines = [];
  for (const mod of [...customClassImports.keys()].sort()) {
    const names = [...customClassImports.get(mod)].sort();
    importLines.push(`import { ${names.join(', ')} } from ${formatLiteral(mod)};`);
  }
  const resourceImports = [];
  if (usesCollection) {
    resourceImports.push('Collection');
  }
  if (usesSingleton) {
    resourceImports.push('Singleton');
  }
  if (resourceImports.length > 0) {
    importLines.push(`import { ${resourceImports.join(', ')} } from '../resource.js';`);
  }
  if (usesSegment) {
    importLines.push("import { segment, type Transport } from '../transport.js';");
  } else {
    importLines.push("import type { Transport } from '../transport.js';");
  }
  if (importedEntityTypes.size > 0) {
    const sortedTypes = [...importedEntityTypes].sort();
    importLines.push(`import type {\n${sortedTypes.join(',\n')},\n} from './entities.js';`);
  }

  const chunks = [
    GENERATED_BANNER,
    `${importLines.join('\n')}\n`,
    formatJsDoc([
      'Makes foreign-key fields referencing the parent resource optional on nested collection inputs.',
    ]) + 'export type NestedInput<I, K extends keyof I> = Omit<I, K> & Partial<Pick<I, K>>;\n',
    ...classBlocks,
    formatJsDoc(['Base class exposing all top-level Kong Admin API resource collections.']) +
      'export class KongResources {\n' +
      '/** HTTP transport used by resource collections. */\n' +
      'protected readonly transport: Transport;\n' +
      `${kongResourcesProps.join('\n')}\n\n` +
      '/** Creates all top-level resource collections bound to the given transport. */\n' +
      'constructor(transport: Transport) {\n' +
      'this.transport = transport;\n' +
      `${kongResourcesInits.join('\n')}\n` +
      '}\n' +
      '}\n',
    formatJsDoc([
      'Regular Admin API path templates served by the generated resource classes, with path parameters written as `{}`.',
    ]) +
      `export const RESOURCE_TEMPLATES: readonly string[] = [\n${templates.map(formatLiteral).join(',\n')},\n];\n`,
  ];

  return chunks.join('\n');
}

async function main() {
  const args = process.argv.slice(2);
  const checkOnly = args.includes('--check');
  const unknownArgs = args.filter((arg) => arg !== '--check');
  if (unknownArgs.length > 0) {
    throw new Error(`Unknown arguments: ${unknownArgs.join(', ')}`);
  }

  const prettierConfig = await readJson(path.join(REPO_ROOT, '.prettierrc.json'));
  const resourcesJson = await readJson(path.join(REPO_ROOT, 'schemas', 'resources.json'));
  const entityContext = await loadEntityContext(resourcesJson);

  const outputs = [
    {
      relPath: 'src/generated/plugins.ts',
      raw: await generatePluginsSource(entityContext),
    },
    {
      relPath: 'src/generated/entities.ts',
      raw: generateEntitiesSource(resourcesJson, entityContext),
    },
    {
      relPath: 'src/generated/resources.ts',
      raw: generateResourcesSource(resourcesJson, entityContext),
    },
  ];

  const mismatched = [];
  for (const item of outputs) {
    const absPath = path.join(REPO_ROOT, item.relPath);
    const formatted = await prettier.format(item.raw, {
      ...prettierConfig,
      filepath: absPath,
    });

    if (checkOnly) {
      let existing = null;
      try {
        existing = await readFile(absPath, 'utf8');
      } catch (err) {
        if (!(err && typeof err === 'object' && 'code' in err && err.code === 'ENOENT')) {
          throw err;
        }
      }
      if (existing !== formatted) {
        mismatched.push(item.relPath);
      }
    } else {
      await mkdir(path.dirname(absPath), { recursive: true });
      await writeFile(absPath, formatted, 'utf8');
    }
  }

  if (checkOnly) {
    if (mismatched.length > 0) {
      console.error('Generated files are out of date:');
      for (const relPath of mismatched) {
        console.error(`  - ${relPath}`);
      }
      process.exit(1);
    }
    console.log(`Generated files are up to date (${outputs.length} files).`);
  } else {
    console.log(`Generated ${outputs.map((o) => o.relPath).join(', ')}`);
  }
}

main().catch((err) => {
  console.error(err instanceof Error ? err.message : String(err));
  process.exit(1);
});
